SELECT s1.`c0` AS `id`, s1.`c1` AS `doubled` FROM (SELECT s2.`c3` AS `c0`, s2.`c4` AS `c1` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s3.`c0` AS `c3`, (CAST(s3.`c2` AS BIGINT) * CAST(2 AS BIGINT)) AS `c4` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2` FROM (SELECT `id` AS `c0`, `customer` AS `c1`, `amount` AS `c2` FROM `orders`) AS s4 WHERE ((CAST(10 AS BIGINT) < s4.`c2`) IS TRUE)) AS s3) AS s2) AS s1
